// src/utils/sfx.js
//
// Small helper for the short game sound effects. Every file lives in
// public/sounds and is generated by frontend/scripts/generate-sounds.mjs.
//
// Two rules keep audio from ever being a problem:
//   * playback failures are swallowed - browsers block autoplay until the user
//     has interacted, and that must never surface as an error;
//   * volumes are set explicitly per effect, because these sounds are meant to sit
//     under the music rather than compete with it.
import { asset } from "./assetUrl.js";

/** Create an effect from a public/ path with its own volume (0..1). */
export const createSfx = (path, volume = 0.4) => {
  const audio = new Audio(asset(path));
  audio.volume = Math.min(1, Math.max(0, volume));
  return audio;
};

/** Play an effect from the start, ignoring anything the browser refuses. */
export const playSfx = (audio) => {
  if (!audio) return;
  try {
    audio.currentTime = 0;
    const played = audio.play();
    if (played && typeof played.catch === "function") played.catch(() => {});
  } catch {
    // A sound is a nice-to-have; never let it interfere with the game.
  }
};

export default playSfx;
